import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{o as i,c as l,a8 as o}from"./chunks/vendor-scheduler.BuXoCeGx.js";const m=JSON.parse('{"title":"设计理念","description":"为什么把 xiaoye-components 收束成基础层 + 中后台业务增强层。","frontmatter":{"title":"设计理念","description":"为什么把 xiaoye-components 收束成基础层 + 中后台业务增强层。","outline":"deep"},"headers":[],"relativePath":"guide/why-xiaoye.md","filePath":"guide/why-xiaoye.md","lastUpdated":1774860317000}'),t={name:"guide/why-xiaoye.md"};function r(n,a,d,c,h,s){return i(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="设计理念" tabindex="-1">设计理念 <a class="header-anchor" href="#设计理念" aria-label="Permalink to &quot;设计理念&quot;">​</a></h1><p>这页先解释 <code>xiaoye-components</code> 为什么要收束成“基础层 + 中后台业务增强层”双产品线，而不是继续把所有能力混在同一个包里。</p><p class="xy-section-lead"> 这个项目的目标不是把所有能力都塞进一个入口，而是让基础层保持通用、增强层承接中后台高频闭环，把页面编排和请求链路做顺手、做稳定、做成文档能直接复用的形态。 </p><h2 id="为什么做这次分层" tabindex="-1">为什么做这次分层 <a class="header-anchor" href="#为什么做这次分层" aria-label="Permalink to &quot;为什么做这次分层&quot;">​</a></h2><p>很多团队在做后台系统时，真正卡住的不是“有没有 Button / Input / Table”，而是下面这些问题：</p><ul><li>基础组件能单独工作，但放到同一页里以后，请求、筛选、批量动作、详情、编辑开始打架。</li><li>单个组件 API 看得见，但页面级闭环很难快速拼出来。</li><li>通用组件和后台专属能力混在一起以后，边界越来越模糊。</li></ul><p>这个项目想解决的，就是这些更贴近日常开发的问题。</p><h2 id="双产品线各自负责什么" tabindex="-1">双产品线各自负责什么 <a class="header-anchor" href="#双产品线各自负责什么" aria-label="Permalink to &quot;双产品线各自负责什么&quot;">​</a></h2><h3 id="基础层保持中性" tabindex="-1">基础层保持中性 <a class="header-anchor" href="#基础层保持中性" aria-label="Permalink to &quot;基础层保持中性&quot;">​</a></h3><p><code>xiaoye-components</code> 负责原子组件、通用容器、基础输入、基础数据展示和基础浮层，不再混入过多中后台专属业务语义。</p><h3 id="增强层承接页面级闭环" tabindex="-1">增强层承接页面级闭环 <a class="header-anchor" href="#增强层承接页面级闭环" aria-label="Permalink to &quot;增强层承接页面级闭环&quot;">​</a></h3><p><code>xiaoye-pro-components</code> 负责把 <code>SearchForm / ProTable / RequestForm / CrudPage / DetailPage</code> 这类中后台高频链路做成正式公开 API。</p><h3 id="中文优先的示例" tabindex="-1">中文优先的示例 <a class="header-anchor" href="#中文优先的示例" aria-label="Permalink to &quot;中文优先的示例&quot;">​</a></h3><p>文档继续保持中文优先，让团队内部讨论、复制示例和调试页面时不需要额外做术语转换。</p><h2 id="双产品线分别适合什么" tabindex="-1">双产品线分别适合什么 <a class="header-anchor" href="#双产品线分别适合什么" aria-label="Permalink to &quot;双产品线分别适合什么&quot;">​</a></h2><ul><li><code>xiaoye-components</code><ul><li>通用 Vue 3 页面</li><li>管理台和业务台的基础控件层</li><li>需要中性基础组件的项目</li></ul></li><li><code>xiaoye-pro-components</code><ul><li>后台管理系统</li><li>SaaS 管理台</li><li>中后台业务平台</li><li>需要快速交付页面闭环的内部工具项目</li></ul></li></ul><h2 id="当前不打算解决什么" tabindex="-1">当前不打算解决什么 <a class="header-anchor" href="#当前不打算解决什么" aria-label="Permalink to &quot;当前不打算解决什么&quot;">​</a></h2><ul><li>基础层直接承接大量页面容器和工作流能力</li><li>低代码设计器或自定义规则 DSL</li><li>BPMN 工作流引擎或后端 SDK</li><li>把权限、审批、请求系统做成强绑定业务框架</li></ul><div class="warning custom-block"><p class="custom-block-title">当前边界</p><p>如果你的项目核心需求是“一个包里同时承接基础层、增强层、工作流和业务引擎”，那么当前这套分层策略并不打算往那个方向走。</p></div><h2 id="文档写作约定" tabindex="-1">文档写作约定 <a class="header-anchor" href="#文档写作约定" aria-label="Permalink to &quot;文档写作约定&quot;">​</a></h2><ul><li>先解释这是基础层还是增强层，再给示例和 API。</li><li>优先用真实页面语境描述增强件，而不是只写抽象属性名。</li><li>聚焦当前版本已经稳定可用的能力，不提前承诺未落地的引擎能力。</li></ul><h2 id="推荐怎么继续读" tabindex="-1">推荐怎么继续读 <a class="header-anchor" href="#推荐怎么继续读" aria-label="Permalink to &quot;推荐怎么继续读&quot;">​</a></h2><ol><li>如果你想先确认基础层覆盖了哪些能力，继续看 <a href="/components/overview">组件总览</a>。</li><li>如果你更关心真实后台页面怎么组合，直接看 <a href="/pro-components/overview">增强组件总览</a> 和 <a href="/examples/admin">管理后台闭环示例</a>。</li><li>如果你已经准备开始接入项目，回到 <a href="/guide/quick-start">快速开始</a>。</li></ol>',23)])])}const x=e(t,[["render",r]]);export{m as __pageData,x as default};
